/* @autogenerated */
package net.civeira.phylax.integrationtest.persistence;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;

import javax.sql.DataSource;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;

import net.civeira.phylax.common.crypto.PasswordHasher;
import net.civeira.phylax.common.crypto.SecretDigester;
import net.civeira.phylax.feature.oauth.userinvitation.domain.InvitationRecord;
import net.civeira.phylax.feature.oauth.userinvitation.infrastructure.driven.InvitationAcceptAdapter;
import net.civeira.phylax.feature.oauth.userinvitation.infrastructure.driven.InvitationLookupAdapter;
import net.civeira.phylax.feature.oauth.userinvitation.infrastructure.driven.InvitationStoreAdapter;

/**
 * Invitations against MariaDB (task 2.2): a link is found by the digest of its token only in its
 * tenant; of concurrent acceptances only one creates the account; cancel and resend only touch a
 * pending invitation of the tenant, and resend makes the old link useless.
 */
@Tag("mariadb")
@ExtendWith(MariaDbSchema.class)
class InvitationMariaDbTest {

  private static final String TENANT_A = "uid-a";
  private static final String TENANT_B = "uid-b";
  private static final String ADMIN = "admin-a";

  private DataSource dataSource;
  private final SecretDigester digester = new SecretDigester("t0:test-digest-pepper", "t0");
  private InvitationLookupAdapter lookup;
  private InvitationStoreAdapter store;
  private InvitationAcceptAdapter accept;

  @BeforeEach
  void setUp(DataSource dataSource) throws SQLException {
    this.dataSource = dataSource;
    lookup = new InvitationLookupAdapter(dataSource, digester);
    store = new InvitationStoreAdapter(dataSource, digester);
    accept = new InvitationAcceptAdapter(dataSource, new PasswordHasher());
    try (Connection c = dataSource.getConnection()) {
      c.createStatement().execute("DELETE FROM access_user_invitation");
      c.createStatement().execute("DELETE FROM identity_user");
      c.createStatement().execute("DELETE FROM identity_tenant_config");
      c.createStatement().execute("DELETE FROM identity_tenant");
      tenant(c, TENANT_A, "tenant-a");
      tenant(c, TENANT_B, "tenant-b");
      try (PreparedStatement ps =
          c.prepareStatement("INSERT INTO identity_user (uid, version, email,"
              + " name, password, tenant, enabled) VALUES (?, 0, ?, ?, 'x', ?, 1)")) {
        ps.setString(1, ADMIN);
        ps.setString(2, "admin@a.example");
        ps.setString(3, "admin@a.example");
        ps.setString(4, TENANT_A);
        ps.execute();
      }
    }
  }

  private static void tenant(Connection c, String uid, String name) throws SQLException {
    try (PreparedStatement ps = c.prepareStatement("INSERT INTO identity_tenant"
        + " (uid, version, domain, enabled, mark_for_delete, name, root)"
        + " VALUES (?, 0, ?, 1, 0, ?, 0)")) {
      ps.setString(1, uid);
      ps.setString(2, name + ".example");
      ps.setString(3, name);
      ps.execute();
    }
  }

  private void invitation(String uid, String token, String email, Instant expires)
      throws SQLException {
    try (Connection c = dataSource.getConnection();
        PreparedStatement ps = c.prepareStatement("INSERT INTO access_user_invitation (uid,"
            + " version, created_at, email, expires_at, status, token_hash, invited_by, tenant)"
            + " VALUES (?, 0, ?, ?, ?, 'PENDING', ?, ?, ?)")) {
      ps.setString(1, uid);
      ps.setTimestamp(2, Timestamp.from(Instant.now()));
      ps.setString(3, email);
      ps.setTimestamp(4, Timestamp.from(expires));
      ps.setString(5, digester.digest(token));
      ps.setString(6, ADMIN);
      ps.setString(7, TENANT_A);
      ps.execute();
    }
  }

  private String status(String uid) throws SQLException {
    try (Connection c = dataSource.getConnection();
        PreparedStatement ps =
            c.prepareStatement("SELECT status FROM access_user_invitation WHERE uid = ?")) {
      ps.setString(1, uid);
      try (ResultSet rs = ps.executeQuery()) {
        rs.next();
        return rs.getString(1);
      }
    }
  }

  private int users(String email) throws SQLException {
    try (Connection c = dataSource.getConnection();
        PreparedStatement ps = c
            .prepareStatement("SELECT COUNT(*) FROM identity_user WHERE name = ? AND tenant = ?")) {
      ps.setString(1, email);
      ps.setString(2, TENANT_A);
      try (ResultSet rs = ps.executeQuery()) {
        rs.next();
        return rs.getInt(1);
      }
    }
  }

  private static Instant inAWeek() {
    return Instant.now().plus(7, ChronoUnit.DAYS).truncatedTo(ChronoUnit.SECONDS);
  }

  @Test
  void link_isFoundByItsToken_onlyInItsTenant() throws Exception {
    invitation("inv-1", "raw-token", "bob@a.example", inAWeek());

    Optional<InvitationRecord> found = lookup.findByToken("raw-token", TENANT_A);
    Assertions.assertTrue(found.isPresent());
    Assertions.assertTrue(found.get().open(Instant.now()));
    Assertions.assertEquals("bob@a.example", found.get().email());
    Assertions.assertTrue(lookup.findByToken("raw-token", TENANT_B).isEmpty());
    Assertions.assertTrue(lookup.findByToken("other-token", TENANT_A).isEmpty());
    Assertions.assertTrue(lookup.findPendingByEmail("bob@a.example", TENANT_A).isPresent());
  }

  @Test
  void concurrentAcceptances_createASingleAccount() throws Exception {
    invitation("inv-1", "raw-token", "bob@a.example", inAWeek());

    List<Optional<String>> results =
        Concurrently.run(8, () -> accept.acceptAndCreateUser("inv-1", "a-good-password"));

    Assertions.assertEquals(1, results.stream().filter(Optional::isPresent).count());
    Assertions.assertEquals(1, users("bob@a.example"));
    Assertions.assertEquals("ACCEPTED", status("inv-1"));
    Assertions.assertTrue(accept.acceptAndCreateUser("inv-1", "a-good-password").isEmpty());
    Assertions.assertFalse(lookup.findByToken("raw-token", TENANT_A).get().open(Instant.now()));
  }

  @Test
  void expiredInvitation_isNotAccepted() throws Exception {
    invitation("inv-1", "raw-token", "bob@a.example", Instant.now().minusSeconds(60));

    Assertions.assertFalse(lookup.findByToken("raw-token", TENANT_A).get().open(Instant.now()));
    Assertions.assertTrue(accept.acceptAndCreateUser("inv-1", "a-good-password").isEmpty());
    Assertions.assertEquals(0, users("bob@a.example"));
  }

  @Test
  void existingAccount_refusesTheAcceptance() throws Exception {
    invitation("inv-1", "raw-token", "admin@a.example", inAWeek());

    Assertions.assertTrue(accept.acceptAndCreateUser("inv-1", "a-good-password").isEmpty());
    Assertions.assertEquals("PENDING", status("inv-1"));
  }

  @Test
  void cancel_onlyAPendingInvitationOfTheTenant() throws Exception {
    invitation("inv-1", "raw-token", "bob@a.example", inAWeek());

    Assertions.assertFalse(store.cancel("inv-1", TENANT_B));
    Assertions.assertEquals("PENDING", status("inv-1"));
    Assertions.assertTrue(store.cancel("inv-1", TENANT_A));
    Assertions.assertEquals("CANCELLED", status("inv-1"));
    Assertions.assertFalse(store.cancel("inv-1", TENANT_A));
    Assertions.assertTrue(accept.acceptAndCreateUser("inv-1", "a-good-password").isEmpty());
  }

  @Test
  void resend_replacesTheLink_onlyForAPendingInvitationOfTheTenant() throws Exception {
    invitation("inv-1", "raw-token", "bob@a.example", inAWeek());
    OffsetDateTime later = OffsetDateTime.now(ZoneOffset.UTC).plusDays(3);

    Assertions.assertTrue(store.refresh("inv-1", TENANT_B, "new-token", later).isEmpty());
    var data = store.refresh("inv-1", TENANT_A, "new-token", later);
    Assertions.assertTrue(data.isPresent());
    Assertions.assertEquals("bob@a.example", data.get().inviteeEmail());
    Assertions.assertEquals("admin@a.example", data.get().inviterEmail());
    Assertions.assertTrue(lookup.findByToken("raw-token", TENANT_A).isEmpty(), "Old link");
    Assertions.assertTrue(lookup.findByToken("new-token", TENANT_A).isPresent());

    store.cancel("inv-1", TENANT_A);
    Assertions.assertTrue(store.refresh("inv-1", TENANT_A, "third", later).isEmpty());
  }
}
